import{_ as i,o as n,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const b=JSON.parse('{"title":"Installations- und Verbindungsprobleme beheben","description":"","frontmatter":{"title":"Installations- und Verbindungsprobleme beheben","source_pageid":1455,"source_revision":7120},"headers":[],"relativePath":"hilfe/probleme/troubleshooting-installation-schild-nrw-3.md","filePath":"hilfe/probleme/troubleshooting-installation-schild-nrw-3.md"}'),a={name:"hilfe/probleme/troubleshooting-installation-schild-nrw-3.md"};function s(l,e,o,h,d,c){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="installations-und-verbindungsprobleme-beheben" tabindex="-1">Installations- und Verbindungsprobleme beheben <a class="header-anchor" href="#installations-und-verbindungsprobleme-beheben" aria-label="Permalink to &quot;Installations- und Verbindungsprobleme beheben&quot;">​</a></h1><p>Grenzen Sie Fehler bei Migration, Reportverzeichnissen, Statistikbibliotheken und Connection-Dateien ein. Die Abschnitte sind nach dem jeweils beobachteten Problem gegliedert.</p><h2 id="die-migration-von-schild-nrw-2-zum-svws-server-scheitert" tabindex="-1">Die Migration von SchILD-NRW 2 zum SVWS-Server scheitert <a class="header-anchor" href="#die-migration-von-schild-nrw-2-zum-svws-server-scheitert" aria-label="Permalink to &quot;Die Migration von SchILD-NRW 2 zum SVWS-Server scheitert&quot;">​</a></h2><p>Wurden vor der Migration die <a href="/administration/installation/installation-svws-server-und-schild-nrw-3.html#vorbereitende-maßnahmen">vorbereitenden Maßnahmen</a> durchgeführt?</p><p>Sichten Sie die Log-Datei, welche bei der Migration angefertigt wurde. Sind hier fehlerhafte Prozesse zu finden?</p><p>Handelt es sich um eine Migration einer SQL-Datenbank eines Linux-Systems? Dann vergleichen Sie die Groß- und Kleinschreibung der SQL-Tabellen mit der erwarteten Groß- und Kleinschreibung der schild2000n.mdb im Unterverzeichnis Vorlagen. Passen Sie abweichende Schreibweisen an.</p><p>Ist die Access-MDB zu alt? Dann führen Sie zunächst mit dem Migrationstool für SchILD-NRW 2 eine Migration in eine leere schild2000n.mdb durch. Sie finden die Vorlage im Unterverzeichnis Vorlagen von SchILD-NRW 2.</p><p>Die Migration scheitert, ohne die Fehlerursache eingrenzen zu können. Führen Sie in diesem Fall zunächst eine Migration der SchILD-NRW 2 Datenbank in eine leere schild2000n.mdb durch. Hierdurch werden fehlende Primärschlüssel neu gesetzt und inkonsistente Datensätze herausgefiltert und protokolliert.</p><h2 id="reports-erscheinen-nicht-in-schild-nrw-3" tabindex="-1">Reports erscheinen nicht in SchILD-NRW 3 <a class="header-anchor" href="#reports-erscheinen-nicht-in-schild-nrw-3" aria-label="Permalink to &quot;Reports erscheinen nicht in SchILD-NRW 3&quot;">​</a></h2><p>Reports tauchen in SchILD-NRW 3 nicht auf, obwohl sie im Report-Verzeichnis <em>SchILD-Reports</em> abgelegt wurden.</p><p>Das Verzeichnis SchILD-Reports gehört nicht wie bei SchILD-NRW 2 in das <em>SchILD-Installationsverzeichnis</em> (z.B. <code>C:\\SchILD-NRW3\\</code>) sondern in das SVWS-Arbeitsverzeichnis (z.B. <code>S:\\SVWS-Arbeitsverzeichnis\\</code>). Der Pfad zum SVWS-Arbeitsverzeichnis wird in der admin.ini im SchILD-NRW 3 Installationsverzeichnis gespeichert.</p><h2 id="statistikbibliotheken-registrieren" tabindex="-1">Statistikbibliotheken registrieren <a class="header-anchor" href="#statistikbibliotheken-registrieren" aria-label="Permalink to &quot;Statistikbibliotheken registrieren&quot;">​</a></h2><p>Wurden die Statistik-dlls nicht korrekt auf dem Windows-Klienten registriert, kann es zu Fehlern mit ASDPC und den Statistikprüfungen in SchILD-NRW kommen.</p><p>Konsultieren Sie den Artikel zur <a href="/hilfe/probleme/hilfe-bei-problemen-verwaltung-statistik-fuer-it-nrw.html">Hilfe bei Problemen zur Statistik</a>, um die Dateien einer SchILD-NRW-Installation nachträglich zu registrieren.</p><h2 id="statistik-dll-konflikte-bei-paralleler-installation-von-schild-nrw-2" tabindex="-1">Statistik.dll-Konflikte bei paralleler Installation von SchILD-NRW 2 <a class="header-anchor" href="#statistik-dll-konflikte-bei-paralleler-installation-von-schild-nrw-2" aria-label="Permalink to &quot;Statistik.dll-Konflikte bei paralleler Installation von SchILD-NRW 2&quot;">​</a></h2><p>Werden mehrere Installationen von SchILD-NRW 2 und/oder SchILD-NRW 3 parallel betrieben, kann es zu Problemen mit der Statistik.dll kommen, da ein Windows-Klient nur die jeweils zuletzt registrierte Datei verwendet.</p><p>Konsultieren Sie den Artikel zur <a href="/hilfe/probleme/hilfe-bei-problemen-verwaltung-statistik-fuer-it-nrw.html">Hilfe bei Problemen zur Statistik</a>, um die Dateien einer SchILD-NRW-Installation nachträglich zu registrieren.</p><p>Nehmen Sie für weitere Ausführungen hierzu das Tutorial zur <a href="/hilfe/probleme/fehleranalyse-zur-statistik-tutorial.html">Fehler bei der Statistikvorbereitung und Abgabe beheben</a> zur Kenntnis.</p><h2 id="erstellen-der-con-datei" tabindex="-1">Erstellen der .con-Datei <a class="header-anchor" href="#erstellen-der-con-datei" aria-label="Permalink to &quot;Erstellen der .con-Datei&quot;">​</a></h2><p>Wenn der Datenbankserver läuft, SchILD-NRW 3 aber keine Verbindung herstellen kann, prüfen Sie die Verbindungsdateien (<strong>Connection-Files</strong>). Möglicherweise wurden sie nicht korrekt erstellt.</p><p>Zum nachträglichen Erstellen starten Sie <code>SchILD_DBConfig.exe</code> aus dem Installationsverzeichnis von SchILD-NRW 3 als Windows-Administrator. Tragen Sie die Verbindungsdaten ein. Im Bereich <strong>Datenbank</strong> steht vor der Adresse kein <code>https://</code>; im Bereich <strong>SVWS-Server</strong> ist dieser Zusatz erforderlich.</p><p>Entscheidend ist das von SchILD verwendete <strong>Arbeitsverzeichnis</strong>: Die <code>.con</code>-Datei muss dort im Unterordner <code>Connection-Files</code> liegen. Bei einem gemeinsamen Arbeitsverzeichnis verwenden die Clients dieselbe Datei. Prüfen Sie außerdem die UTF-8-Kodierung und die exakte Groß- und Kleinschreibung des Schemanamens; siehe <a href="https://doku.svws-nrw.de/deployment/Schild-NRW3/" target="_blank" rel="noreferrer">Verbindungskonfiguration in der SVWS-Dokumentation</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Troubleshooting_Installation_SchILD-NRW_3" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7120.</p>',24)])])}const m=i(a,[["render",s]]);export{b as __pageData,m as default};
